    var rows = all.map(function (o) {
      var ps = packState(o), btn = ps === 'Pending' ? '<button class="btn sm" data-a="packstart" data-c="' + esc(o.dealerCode) + '" data-id="' + esc(o.id) + '">Start packing</button>' : (ps === 'In progress' ? '<button class="btn blue sm" data-a="packopen" data-c="' + esc(o.dealerCode) + '" data-id="' + esc(o.id) + '">Open checklist</button>' : '<span class="tag live">Packed</span>' + whPickupBtn(o));
      return '<tr class="' + rowCls(o) + '"><td><b>' + esc(o.id) + '</b>' + (o.demo ? ' <span class="tag demo">DEMO</span>' : '') + whTick(o) + '<br><span class="osm">' + fdt2(o.date) + '</span><br><button class="btn ghost sm" type="button" data-a="oopen" data-c="' + esc(o.dealerCode) + '" data-id="' + esc(o.id) + '">Open</button><div class="rowbtns" style="margin-top:6px">' + docBtns(o, false) + '</div></td><td>' + esc(o.dealerName) + '</td><td>' + o.items.map(function (l) { return esc(l.product.split(' (')[0]) + ' ' + esc(l.variant) + (l.flavour ? ' \u00B7 ' + esc(l.flavour) : '') + ' \u00D7 ' + l.qty; }).join('<br>') + '</td><td>' + (o.invoice ? esc(o.invoice.no) : '<span class="osm">none</span>') + '</td><td>' + esc(ps) + '</td><td class="r"><div class="rowbtns" style="justify-content:flex-end">' + btn + '<button class="btn ghost sm" data-a="doc" data-c="' + esc(o.dealerCode) + '" data-id="' + esc(o.id) + '" data-t="inv">Invoice</button></div></td></tr>';
    }).join('');
