    var items = o.items.map(function (f) { return '<div class="fbrow"><span class="thumb" style="width:56px;height:56px">' + (SEL.imgOf(f.pid) ? '<img src="' + SEL.imgOf(f.pid).src + '" alt="">' : '') + '</span><div style="flex:1;min-width:0"><b>' + esc(f.name) + '</b><small class="osm" style="display:block">' + esc(f.code) + ' \u00B7 ' + esc(bn(f.brand)) + ' \u00B7 valued ' + inr(f.valuation) + ' each \u00B7 ' + f.qty + ' available \u00B7 max ' + f.maxQty + '</small></div><input class="fb-q sel" type="number" min="0" max="' + Math.min(f.maxQty, f.qty) + '" data-f="' + esc(f.id) + '" data-v="' + f.valuation + '" value="' + (co.fb[f.id] || 0) + '" aria-label="Quantity of ' + esc(f.name) + '" style="width:76px"></div>'; }).join('');
    var why = o.reasons.map(function (r) { return '<li>' + esc(r.product + ' ' + r.variant) + ': ' + esc(r.reason) + '</li>'; }).join('');
    openModal('<h2>Add freebies</h2><p class="osm">Qualifying order value <b>' + inr(o.qualifying) + '</b> gives a maximum freebie value of <b>' + inr(o.allowance) + (o.wallet ? ' (includes ' + inr(o.wallet) + ' from the freebie wallet)' : '') + '</b>. It is a maximum, not a purchase: choose up to that value. The amount payable does not change.</p><div class="gstbox"><span>Selected value: <b id="fb-used">' + inr(0) + '</b> of ' + inr(o.allowance) + (o.wallet ? ' (includes ' + inr(o.wallet) + ' from the freebie wallet)' : '') + '</span></div>' +
      (why ? '<p class="osm" style="margin-top:8px"><b>Not eligible for freebies:</b></p><ul class="osm" style="margin:2px 0 8px 18px">' + why + '</ul>' : '') + (items || '<p class="osm" style="margin:12px 0">No freebies are available for this dealer and order value right now.</p>') + '<p class="err" id="fb-err" role="alert"></p><div class="rowbtns"><button class="btn" type="button" data-a="fbconfirm">Confirm freebies</button><button class="btn ghost" type="button" data-a="lmcancel">Cancel</button></div>');
