      '<div class="field full"><label><input type="checkbox" id="fb-act"' + (f.active ? ' checked' : '') + '> Active</label></div></div><p class="err" id="fb-err2" role="alert"></p><div class="rowbtns"><button class="btn" type="button" data-a="fbsave">Save freebie</button><button class="btn ghost" type="button" data-a="fbcancel">Cancel</button></div></section>';
