        (ses.length ? ses.map(function (s, n) { var c = DB.dayCalc(s.in, s.out); return '<div class="srow2"><div><small>Sign-in ' + (n + 1) + '</small><b>' + tm(s.in) + '</b></div><div><small>Sign-out</small><b>' + (s.out ? tm(s.out) : 'Not signed out') + '</b></div><div><small>Time</small><b>' + (s.out ? hm(c.span) : '\u2014') + '</b></div></div>' + (c.late ? '<span class="osm">Arrived ' + c.late + ' min late. </span>' : '') + (s.out && c.early ? '<span class="osm">Left ' + c.early + ' min early. </span>' : '') + (s.src && s.src !== 'self' && s.src !== 'sample' ? '<span class="osm">(' + esc(s.src) + ')</span>' : ''); }).join('') + '<p class="osm" style="margin-top:8px">Net working time ' + hm(r2 ? r2.net : 0) + (r2 && r2.ot ? ' \u00B7 overtime ' + hm(r2.ot) : '') + ' (1-hour lunch deducted once).</p>' : '<p class="osm">No sign-in or sign-out on this day.</p>') + '</div>';
